package org.kanger;
import java.util.*;
import org.kanger.ContextProductionCapture.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextUniversalSignedUnitRounds.*;
import org.kanger.ContextUniversalSignedUnitRounds.Result;
import org.kanger.ContextUniversalSignedUnitExchange.Exchange;
import org.kanger.ContextWitnessResultTransport.*;

/** Both channels qualify together on the next immutable supplied-cut input. */
public final class ContextUniversalSignedUnitRoundsRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static Snapshot bind(boolean x,String s)throws Exception{return ContextPrivateWitnessPoolRunner.bind(x,s);}
    static ContextUniversalFrozenBranch.Limits full(){return ContextUniversalFrozenBranchRunner.full();}
    static Result run(Snapshot x,List<Snapshot> a,Packet p,Map<Cut,PrivatePool> pools,int rounds){return ContextUniversalSignedUnitRounds.run(x,a,p,pools,null,full(),rounds,WORK);}
    static void incomplete(Result r,String phase,int completed,String why){require(r.status==Status.INCOMPLETE&&r.output==null&&r.symbolicOutput==null&&r.history.isEmpty()&&r.refutations.isEmpty()&&r.completedRounds==completed&&(phase==null||r.phase.equals(phase)),why+": "+r.phase+" "+r.reason);}
    static void refuted(Result r,int round,String why){require(r.status==Status.REFUTED&&r.output==null&&r.symbolicOutput==null&&r.history.isEmpty()&&!r.refutations.isEmpty()&&r.completedRounds==round-1,why+": "+r.phase+" "+r.reason);for(Refutation f:r.refutations.values()){require(f.round==round&&!f.proofs.isEmpty()&&(f.xRefuted||f.foreignRefuted),"checked empty evidence without candidate prefix");Set<org.kanger.ContextUniversalFrozenConstraints.Proof> seen=Collections.newSetFromMap(new IdentityHashMap<org.kanger.ContextUniversalFrozenConstraints.Proof,Boolean>());for(org.kanger.ContextUniversalFrozenConstraints.Proof p:f.proofs)rejection(p,seen);}}
    static void rejection(org.kanger.ContextUniversalFrozenConstraints.Proof p,Set<org.kanger.ContextUniversalFrozenConstraints.Proof> seen){if(!seen.add(p))return;require(p.exchanged==null,"no historical closure/Packet owner hidden in rejection DAG");if(p.unit!=null){rejection(p.unit,seen);rejection(p.horn,seen);}else require(p.original!=null||p.input!=null,"actual native or carried Item proof leaf");ContextUniversalSignedRoundsRunner.auditProof(p,Collections.newSetFromMap(new IdentityHashMap<org.kanger.ContextUniversalFrozenConstraints.Proof,Boolean>()));}
    static Result stable(Result r){require(r.status==Status.STABLE_UNIT_POOLS&&r.output!=null&&r.symbolicOutput!=null&&r.history.size()==r.completedRounds,r.phase+" "+r.reason);Packet p=r.input;Exchange symbolic=null;for(Round n:r.history){require(n.input==p&&n.symbolicInput==symbolic,"actual two-channel predecessor");require(n.symbolicOutput.common==n.barrier.packet&&n.symbolicOutput.barrier==n.barrier,"symbolic rebase tied to actual merged packet");require(n.symbolicOutput.checks.keySet().equals(n.checks.keySet()),"every supplied symbolic cut");for(Cut cut:n.checks.keySet())require(n.checks.get(cut).exchange==n.symbolicInput&&n.checks.get(cut).common==n.input&&n.symbolicOutput.checks.get(cut)==n.checks.get(cut)&&n.products.get(cut).transfer==n.barrier.branches.get(cut),"all checks/products share owning fixed and symbolic input");require(n.symbolicChanged==!ContextUniversalSignedUnitExchange.sameContents(symbolic,n.symbolicOutput,WORK),"full symbolic Source/minimum pools compared");p=n.barrier.packet;symbolic=n.symbolicOutput;}Round last=r.history.get(r.history.size()-1);require(!last.symbolicChanged&&!last.commonChanged&&!last.privateChanged&&!last.barrier.localChanged&&r.symbolicOutput==last.symbolicOutput,"stop only complete two-channel/private stability");return r;}
    static void original()throws Exception {
        String rule="!@w p(w,1)->q(w,1);",pos="!@w p(w,1);",neg="!@w ~q(w,1);";Snapshot x=bind(true,"!anchor(1); "+rule),a=bind(false,pos),b=bind(false,neg);Packet input=ContextPrivateWitnessPoolRunner.common(x);Set<Source> expected=new HashSet<>(Arrays.asList(ContextPrivateWitnessPoolRunner.source(x,rule),ContextPrivateWitnessPoolRunner.source(a,pos),ContextPrivateWitnessPoolRunner.source(b,neg)));
        for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,b),Arrays.asList(b,a))){Result r=run(x,order,input,Collections.emptyMap(),8);refuted(r,2,"both universal products qualify next round in either order");for(Snapshot affected:Arrays.asList(a,b)){Refutation f=r.refutations.get(Cut.of(affected));require(f!=null&&f.symbolicIdentity!=null&&!f.inputIdentity.equals(input.identity)&&f.proofs.stream().anyMatch(p->p.support.depth==2&&p.support.sources.equals(expected)),"exact symbolic empty2 Sources and next input identities");}}
        incomplete(run(x,Arrays.asList(a,b),input,Collections.emptyMap(),1),"round-limit",1,"cannot expose unqualified symbolic proposal");
        ContextUniversalFrozenBranch.Limits bound=new ContextUniversalFrozenBranch.Limits(16,16,0,512,256,WORK,512,512);incomplete(ContextUniversalSignedUnitRounds.run(x,Arrays.asList(a,b),input,Collections.emptyMap(),null,bound,8,WORK),"symbolic-collection",0,"symbolic fact bound no candidate prefix");
        Snapshot bad=bind(false,"!a(1)||b(1);");incomplete(run(x,Arrays.asList(a,b,bad),input,Collections.emptyMap(),8),"checks",0,"unsupported later cut prevents partial output");
        require(ContextUniversalSignedRounds.run(x,Arrays.asList(a,b),input,Collections.emptyMap(),full(),1,WORK).status==ContextUniversalSignedRounds.Status.STABLE_SIGNED_POOLS,"legacy fixed-only scope unchanged");
    }
    static void growthAndChain()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@w p(w,1);"),a=bind(false,"!@w p(w,1)->q(w,1);"),b=bind(false,"!@w q(w,1)->p(w,1);");Packet input=ContextPrivateWitnessPoolRunner.common(x);Result r=stable(run(x,Arrays.asList(a,b),input,Collections.emptyMap(),8));require(r.completedRounds==4,"symbolic Source supersets stabilize4 rather than first atom stability");require(r.history.stream().allMatch(n->!n.commonChanged)&&r.history.get(1).symbolicChanged,"unchanged fixed pools cannot hide symbolic Source growth");Result reversed=stable(run(x,Arrays.asList(b,a),input,Collections.emptyMap(),8));require(ContextUniversalSignedUnitExchange.sameContents(r.symbolicOutput,reversed.symbolicOutput,WORK),"order-invariant whole symbolic Source minima");
        Result resumed=ContextUniversalSignedUnitRounds.run(x,Arrays.asList(a,b),r.output.packet,r.output.privatePools,r.symbolicOutput,full(),1,WORK);require(resumed.status==Status.STABLE_UNIT_POOLS&&resumed.completedRounds==1,resumed.phase+" "+resumed.reason);
        Round first=r.history.get(0);try{ContextUniversalSignedUnitExchange.rebase(first.symbolicOutput.prior,r.history.get(1).barrier,WORK);throw new AssertionError("mixed rebase accepted");}catch(IllegalStateException expected){++checks;}
        try{ContextUniversalSignedUnitExchange.rebase(first.symbolicOutput.prior,first.barrier,1);throw new AssertionError("rebase budget accepted");}catch(IllegalStateException expected){++checks;}
        try{r.history.clear();throw new AssertionError("mutable history");}catch(UnsupportedOperationException expected){++checks;}
        incomplete(run(x,Arrays.asList(a,b),input,Collections.emptyMap(),2),"round-limit",2,"Source-only change requires another round");
        Snapshot cx=bind(true,"!anchor(1); !@w p(w,1)->q(w,1);"),ca=bind(false,"!@w p(w,1);"),cb=bind(false,"!@w q(w,1)->r(w,1);"),cc=bind(false,"!@w ~r(w,1);");Packet cp=ContextPrivateWitnessPoolRunner.common(cx);Result chain=run(cx,Arrays.asList(ca,cb,cc),cp,Collections.emptyMap(),8);refuted(chain,3,"two symbolic production barriers then rejection");require(chain.refutations.get(Cut.of(cc)).proofs.stream().anyMatch(p->p.support.depth==3&&p.support.sources.size()==4),"nested symbolic empty3 with full four Sources");
    }
    static void privateAndFixed()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@w @v seed(w,1)&&top(v,1)->p(w,v); !@v top(v,1);"),a=bind(false,"!$w seed(w,1);"),b=bind(false,"!@w @v p(w,v)&&need(v,1)->q(w,v); !need(2,1);");Packet cp=ContextPrivateWitnessPoolRunner.common(x);PrivatePool pool=ContextWitnessResultTransport.privatePool(cp,x,a,WORK);Result r=stable(run(x,Arrays.asList(a,b),cp,Collections.singletonMap(pool.cut,pool),8));require(r.output.packet.items.stream().anyMatch(i->i.atom.predicate.equals("q")&&i.atom.arguments.get(0).origin!=null),"shared symbolic Origin result becomes actual fixed product in independent branch");require(r.output.packet.items.stream().noneMatch(i->i.atom.predicate.equals("seed")),"raw private donor never shared");require(r.output.privatePools.get(pool.cut).common==r.output.packet&&!pool.local.items.stream().anyMatch(i->i.atom.predicate.equals("q")),"private continuation rebased, old pool immutable");
        Source seed=a.primary.get(0).source;for(Item item:r.output.packet.items)if(item.atom.predicate.equals("q")){require(item.atom.arguments.get(0).origin.source.equals(seed),"fixed product keeps original physical private Origin");for(Support support:item.proofs)require(support.sources.contains(seed),"every concrete product alternative retains actual binding Source");}
        incomplete(run(x,Arrays.asList(a,b),cp,Collections.emptyMap(),8),"checks",0,"missing full private witness manifest never publishes symbolic input");
        incomplete(ContextUniversalSignedUnitRounds.run(x,Arrays.asList(a,b),cp,Collections.singletonMap(pool.cut,pool),r.symbolicOutput,full(),8,WORK),"preflight",0,"equal/older common cannot replace exact symbolic rebase basis");
        Snapshot anchor=bind(true,"!anchor(1);"),pa=bind(false,"!@w p(w,1);"),pb=bind(false,"!@w ~p(w,1);");Result independent=stable(run(anchor,Arrays.asList(pa,pb),ContextPrivateWitnessPoolRunner.common(anchor),Collections.emptyMap(),1));require(independent.symbolicOutput.units.isEmpty(),"independent universal opinions still not communalized");
        Snapshot fx=bind(true,"!p(1);"),fa=bind(false,"!@w p(w)->q(w);"),fb=bind(false,"!~q(1);");Result fixed=run(fx,Arrays.asList(fa,fb),ContextPrivateWitnessPoolRunner.common(fx),Collections.emptyMap(),8);refuted(fixed,2,"existing fixed negative products still qualify next round");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("signed-unit-rounds-").toString());original();growthAndChain();privateAndFixed();System.out.println("CONTEXT_UNIVERSAL_SIGNED_UNIT_ROUNDS_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
